Algorithm Countdown
  Define n As Integer <- 3;
  While n > 0 Do
    Write n;
    n <- n - 1;
  EndWhile
  Write "Go!";
EndAlgorithm

Algorithm MoneyBox
  Define day As Integer <- 1;
  Define savedToday As Integer <- 2;
  Define savings As Integer <- 2;
  While savings < 50 Do
    day <- day + 1;
    savedToday <- savedToday + 1;
    savings <- savings + savedToday;
  EndWhile
  Write "Lucía buys the ball on day ", day, " with ", savings, " coins";
EndAlgorithm

Algorithm MoneyBox
  Define price As Integer;
  Read price;
  Define day As Integer <- 1;
  Define savedToday As Integer <- 2;
  Define savings As Integer <- 2;
  While savings < price Do
    day <- day + 1;
    savedToday <- savedToday + 1;
    savings <- savings + savedToday;
  EndWhile
  Write "Day ", day, " with ", savings, " coins";
EndAlgorithm

Algorithm Endless
  Define savings As Integer <- 2;
  Define savedToday As Integer <- 2;
  While savings < 50 Do
    savedToday <- savedToday + 1;
  EndWhile
  Write savings;
EndAlgorithm

Algorithm DictatedMoneyBox
  Define coins As Integer;
  Define savings As Integer <- 0;
  Read coins;
  While coins <> -1 Do
    savings <- savings + coins;
    Read coins;
  EndWhile
  Write "Gathered ", savings, " coins";
EndAlgorithm
